using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class FieldPresenceTests
{
    static WorldSession New()=>new(FieldPresence.Create());
    static void At(WorldSession s,long at){while(s.Seconds<at){s.SetPaused(false);long before=s.Seconds;s.AdvanceTo(at);Assert.True(s.Seconds>before);}}
    static void Pack(WorldSession s)=>Assert.Equal(ResultCode.Accepted,s.HandleSupply(new("request:pack"),s.PlayerControl,true,FieldSupply.Capacity,s.Revision).Code);
    static void Open(WorldSession s)=>Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,RegionalWork.Inbox(s).Single(c=>c.CanOpen).Message,s.Revision).Code);
    static void Deploy(WorldSession s){Pack(s);At(s,2);Open(s);At(s,9);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);}
    [Fact] public void PlayerStartsAtSiteWhileNpcHasItsOwnTrainingMarch(){var s=New();var w=s.DiagnosticSnapshot();Assert.True(w.Region!.Active);Assert.False(FieldPresence.PlayerDeployed(w));Assert.Equal(LocationKind.AtSite,w.Locations.Single(l=>l.Actor==s.PlayerControl).Kind);Assert.Contains(w.Region.Units,u=>u.Commander==ContractFixture.Clerk&&u.Route.Length>0);Assert.Equal(new EntityId("org:house"),w.Units.First(u=>u.Commander==ContractFixture.Clerk).Organization);}
    [Fact] public void NpcMovementAndLocalWorkShareOneClock(){var s=New();var positions=s.DiagnosticSnapshot().Region!.Units.Where(u=>u.Commander==ContractFixture.Clerk).Select(u=>u.Position).ToArray();At(s,2);Open(s);At(s,9);Assert.Contains(s.DiagnosticSnapshot().Tasks,t=>t.Action==ActionKind.Inspect&&t.Execution==ExecutionPhase.Completed);Assert.False(positions.SequenceEqual(s.DiagnosticSnapshot().Region!.Units.Where(u=>u.Commander==ContractFixture.Clerk).Select(u=>u.Position)));Assert.Equal(LocationKind.AtSite,s.GetActorView(s.PlayerControl).Location.Kind);}
    [Fact] public void ReturnDoesNotStopOrTeleportOtherForceOrConsumeOwnFood(){var s=New();Deploy(s);At(s,19);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(false,s.Revision).Code);var w=s.DiagnosticSnapshot();var group=w.Region!.Units.Where(u=>u.Commander==ContractFixture.Clerk).ToArray();long qty=FieldSupply.Carried(w).Quantity;At(s,29);var after=s.DiagnosticSnapshot();Assert.True(after.Region!.Active);Assert.False(FieldPresence.PlayerDeployed(after));Assert.False(group.Select(u=>u.Position).SequenceEqual(after.Region.Units.Where(u=>u.Commander==ContractFixture.Clerk).Select(u=>u.Position)));Assert.Equal(qty,FieldSupply.Carried(after).Quantity);Assert.Equal(LocationKind.AtSite,s.GetActorView(s.PlayerControl).Location.Kind);}
    [Fact] public void SiteBodyAndCourierOriginUseRealSiteNotGarrisonRepresentative(){var s=New();At(s,2);Open(s);Assert.Equal(ResultCode.Accepted,s.InterruptMission(s.DiagnosticSnapshot().Tasks.Single().Id,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.ExplainMission(s.DiagnosticSnapshot().Tasks.Single().Id,s.PlayerControl,MissionReview.Explanation.OwnDecision,s.Revision).Code);var w=s.DiagnosticSnapshot();var expected=NationalRoutes.Nodes.Single(n=>n.Id=="castle").Position;Assert.Equal(expected,s.GetBranchView(s.PlayerControl).Position);Assert.Equal(expected,w.Couriers!.Missions.Last().Origin);Assert.Equal(LocationKind.AtSite,w.Couriers.Missions.Last().DispatchPose!.Location.Kind);}
    [Fact] public void PersonalRoadTravelIsAllowedWhileOtherForceIsActive(){var s=New();Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:road","kofu"),s.Revision).Code);At(s,10);Assert.True(TravelWorld.Active(s.DiagnosticSnapshot()));Assert.False(FieldPresence.PlayerDeployed(s.DiagnosticSnapshot()));Assert.Equal(LocationKind.Traveling,s.GetActorView(s.PlayerControl).Location.Kind);Assert.True(s.GetBranchView(s.PlayerControl).Walking);Assert.NotEqual(FieldWorld.ToWorld(s.DiagnosticSnapshot().Region!.Units.First(u=>u.Commander==s.PlayerControl).Position),s.GetBranchView(s.PlayerControl).Position);}
    [Fact] public void OtherArmyDoesNotGrantControlOrPreventPersonalDeparture(){var s=New();Assert.Equal(ResultCode.NotAvailable,s.IssueRegional(new(new("request:other-force"),s.PlayerControl,ContractFixture.Clerk,RegionalAction.Move,new(0,0),new(10000,0)),s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.IssueRegional(new(new("request:self-from-site"),s.PlayerControl,s.PlayerControl,RegionalAction.Move,new(0,0),new(10000,0)),s.Revision).Code);Pack(s);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(2)][InlineData(10)][InlineData(20)][InlineData(50)]
    public void RestoreSiteOrFieldKeepsNpcMovementAndStockExact(int at){var s=New();if(at>=10)Deploy(s);At(s,at);if(at>=20){Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(false,s.Revision).Code);}s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"presence-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);store.Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));At(s,80);At(host.Current,80);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
    [Theory][InlineData("actors")][InlineData("duplicates")][InlineData("term")][InlineData("clock")]
    public void InvalidPresenceCannotLoad(string kind){var w=FieldPresence.Create();w.Presence=kind switch{"actors"=>w.Presence! with{DeployedActors=[]},"duplicates"=>w.Presence! with{DeployedActors=[ContractFixture.Clerk,ContractFixture.Clerk]},"term"=>w.Presence! with{Terms=w.Presence.Terms with{Source="unknown"}},_=>w.Presence};if(kind=="clock")w.Region=w.Region! with{Active=false};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void OldProfilesCannotReceiveIndependentPresence(){var w=FieldSupply.Create();w.Presence=FieldPresence.Create().Presence;Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void QuietWorldSkippingMatchesFineStepsForPhysicalState(){var a=New();var b=New();At(a,400);for(int at=1;at<=400;at++)At(b,at);var x=a.DiagnosticSnapshot();var y=b.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(x.Region),ContractJson.Write(y.Region));Assert.Equal(ContractJson.Write(x.Supply),ContractJson.Write(y.Supply));Assert.Equal(a.GetBranchView(a.PlayerControl).Position,b.GetBranchView(b.PlayerControl).Position);Assert.Equal(x.NpcWork!.Decisions.Select(d=>(d.Actor,d.At,d.Reason,d.Request,d.Result)).ToArray(),y.NpcWork!.Decisions.Select(d=>(d.Actor,d.At,d.Reason,d.Request,d.Result)).ToArray());}
    [Fact] public void UnseenEnemyTruthDoesNotChangePlayerMap(){ContractWorld Far(long shift){var w=FieldPresence.Create();w.ElapsedSeconds=1;w.Region=w.Region! with{Units=w.Region.Units.Select((u,i)=>u.Commander==RegionalBattle.Enemy?u with{Home=ContinuousWorld.Point("castle",300000+shift+i*10000,-85000),Position=ContinuousWorld.Point("castle",300000+shift+i*10000,-85000),Goal=ContinuousWorld.Point("castle",300000+shift+i*10000,-85000),RouteOrigin=ContinuousWorld.Point("castle",300000+shift+i*10000,-85000),Route=[]}:u).ToArray()};RegionalBattle.Tick(w);ContractValidation.Validate(w);return w;}var a=Far(0);var b=Far(10000);Assert.NotEqual(a.Region!.Units.Last().Position,b.Region!.Units.Last().Position);Assert.Equal(ContractJson.Write(RegionalBattle.View(a,a.PlayerControl)),ContractJson.Write(RegionalBattle.View(b,b.PlayerControl)));}
    [Fact] public void LiteralOldSupplyInitialKeepsItsDefinition(){var w=ContractJson.Read<ContractWorld>(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","supply-f9dcd84-initial.json")));Assert.Null(w.Presence);Assert.Equal(ContractJson.CanonicalHash(FieldSupply.Create("検証配置家臣")),ContractJson.CanonicalHash(w));}

    [Fact] public void QuietDepletionHasIdenticalIntervalsAcrossTimeStepSizes(){var a=New();At(a,400);Assert.False(FieldPresence.NeedsSecondSteps(a.DiagnosticSnapshot(),400));Assert.Equal(ResultCode.Accepted,a.HandleSupply(new("request:small-pack"),a.PlayerControl,true,150,a.Revision).Code);Assert.Equal(ResultCode.Accepted,a.SetRegionalActive(true,a.Revision).Code);var b=new WorldSession(a.DiagnosticSnapshot());At(a,410);for(int at=401;at<=410;at++)At(b,at);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot().Supply),ContractJson.Write(b.DiagnosticSnapshot().Supply));Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot().Region),ContractJson.Write(b.DiagnosticSnapshot().Region));Assert.Equal(0,FieldSupply.Carried(a.DiagnosticSnapshot()).Quantity);Assert.Equal(3,a.DiagnosticSnapshot().Supply!.Uses.Length);}

}
